#!/usr/bin/env node

// 本文件是 citizenweb/release-web.yml 的完整动作入口。
// 所需实现内嵌于本文件，运行时不得导入其它产品或动作脚本。
import { mkdtempSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
